const STORE_KEY='lkp-mockup-v1';
const API_PROJECTS='/api/projects';
function normalizeProject(project){return {...project,id:String(project.id||project._id),sample:project.sample!==false};}
async function apiProject(path='',options={}){
 const response=await fetch(`${API_PROJECTS}${path}`,{...options,headers:{'Content-Type':'application/json',...(options.headers||{})}});
 const body=await response.json().catch(()=>({}));
 if(!response.ok)throw new Error(body.message||`API request failed (${response.status}).`);
 return body;
}
async function loadProjectsFromDatabase(){
 try{const result=await apiProject();data.projects=(result.data||[]).map(normalizeProject);render(false);}
 catch(error){console.warn('Could not load MongoDB projects:',error.message);toast('Database API unavailable. Showing sample projects. Start the API server to use MongoDB CRUD.');}
}
const esc = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const id = prefix => prefix + (globalThis.crypto?.randomUUID?.() || Date.now().toString(36)+Math.random().toString(36).slice(2));
const clone = obj => JSON.parse(JSON.stringify(obj));
let data=clone(SEED), session=null, projectFilter='All', projectQuery='', financeFilter='All', portalTab='overview', storageOK=true;
try { const saved=JSON.parse(localStorage.getItem(STORE_KEY)); if(saved && Object.keys(SEED).every(key=>Array.isArray(saved[key]))) data=saved; } catch { storageOK=false; }
const main=document.querySelector('main');
const modal=document.querySelector('#modal');
const money = n => new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP',maximumFractionDigits:2}).format(n);
const date = s => s ? new Date(s+'T12:00:00').toLocaleDateString('en-PH',{month:'short',day:'numeric',year:'numeric'}) : 'To be confirmed';
const today = () => new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Manila',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const initials = name => name.split(' ').filter(Boolean).slice(0,2).map(x=>x[0]).join('');
const icons={heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8 M3 12h5l2-4 4 8 2-4h5',leaf:'M20 3C6 2 2 9 6 16s16 5 14-13 M5 21l10-12',book:'M12 5v16 M12 5C8 2 4 3 2 4v15c4-2 7-1 10 2 3-3 6-4 10-2V4c-4-2-7-1-10 1',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M18 8a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-4 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',shield:'M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6L12 2 M8 12l3 3 5-6',paw:'M8 13c-7 5-3 10 1 7 2-1 4-1 6 0 4 3 8-2 1-7-2-2-6-2-8 0 M5 4c-3 0-3 6 0 6s3-6 0-6 M10 2c-3 0-3 7 0 7s3-7 0-7 M15 2c-3 0-3 7 0 7s3-7 0-7 M20 4c-3 0-3 6 0 6s3-6 0-6',ball:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0 M2 12h20 M12 2v20 M5 5c7 4 7 10 0 14 M19 5c-7 4-7 10 0 14',fruit:'M12 7c-9-5-13 8-6 13 3 2 4-1 6-1s3 3 6 1c7-5 3-18-6-13 M12 7V3 M12 5c0-4 5-4 6-4-1 4-4 5-6 4',flower:'M12 9c-8-13-15 1-5 4-12 3-2 14 5 3 7 11 17 0 5-3 10-3 3-17-5-4 M12 16v7',arrow:'M4 12h16 M14 6l6 6-6 6'};
const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name]||icons.heart}"></path></svg>`;
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),4500);}
function save(action){if(action)data.audit.unshift({date:new Date().toISOString(),action,actor:session?.name||'Demo visitor'});try{localStorage.setItem(STORE_KEY,JSON.stringify(data));}catch{storageOK=false;toast('Browser storage unavailable. Changes will last only until this page is closed.');}}
function openModal(html){document.querySelector('#modal-content').innerHTML=html;if(!modal.open)modal.showModal();}
function closeModal(){modal.close();document.querySelector('#modal-content').innerHTML='';}
const notice = text => `<div class="notice">${text}</div>`;
const heading = (eyebrow,title,description='') => `<div class="page-heading container"><div class="eyebrow">${eyebrow}</div><h1>${title}</h1>${description?`<p>${description}</p>`:''}</div>`;
function finance(){const income=data.transactions.filter(x=>x.type==='Income').reduce((a,x)=>a+Number(x.amount),0),expense=data.transactions.filter(x=>x.type==='Expense').reduce((a,x)=>a+Number(x.amount),0);return {income,expense,balance:income-expense};}
function stats(){return `<div class="stats"><div class="stat"><strong>08</strong><span>Documented activities</span><small>Supplied report · Apr 2025–Feb 2026</small></div><div class="stat"><strong>100+</strong><span>Spectators assisted</span><small>Holy Monday · Apr 14, 2025</small></div><div class="stat"><strong>51</strong><span>Students in civic education</span><small>Voter registration seminar · Aug 4, 2025</small></div><div class="stat"><strong>01</strong><span>Community at our heart</span><small>Barangay Paco, Obando, Bulacan</small></div></div>`;}
function card(p){return `<article class="project-card">${p.image?`<img src="${esc(p.image)}" alt="LKP ${esc(p.category.toLowerCase())} volunteers in action" loading="lazy">`:`<div class="project-art ${p.category==='Sports'||p.category==='Fundraising'?'gold':''}">${icon(p.icon)}</div>`}<div class="project-body"><div class="project-meta"><span class="badge ${p.status==='Conducted'?'':'gold'}">${esc(p.category)}</span><time datetime="${esc(p.date)}">${date(p.date)}</time></div><h3>${esc(p.title)}</h3><p>${esc(p.summary)}</p><div class="card-bottom"><span>${esc(p.status==='Planned'?'Planned · completion unconfirmed':p.status)}${p.sample?' · DEMO':''}</span><button class="circle-link" data-action="project" data-id="${esc(p.id)}" aria-label="Read about ${esc(p.title)}">↗</button></div></div></article>`;}
function pillars(){return `<div class="pillars">${[['heart','Health & well-being','Showing up with care for our neighbors.'],['leaf','Environment','Protecting the places we call home.'],['ball','Sports & community','Building confidence through teamwork.'],['book','Education & leadership','Helping young people find their voice.']].map(([i,t,p])=>`<div class="pillar">${icon(i)}<h3>${t}</h3><p>${p}</p></div>`).join('')}</div>`;}
function home(){const f=finance();return `
  <section class="hero"><div class="container hero-grid"><div class="hero-copy"><div class="eyebrow">Paco, Obando, Bulacan · Youth in action</div><h1>Lakas ng<br>Kabataan.<br><em>Lakas ng Masa.</em></h1><p>Big change begins close to home. We bring young people together to care, lead, and build a stronger community in Barangay Paco.</p><div class="actions"><a class="button" href="#volunteer">Find your place in LKP ${icon('arrow')}</a><a class="text-link" href="#projects">See our work ↗</a></div><div class="registration-line">${icon('shield')} NYC-registered community-based organization · ${ORGANIZATION.urn}</div></div><div class="hero-visual"><img class="hero-photo" src="assets/community.jpg" alt="LKP volunteers gathered together during Go Paw Paco" fetchpriority="high"><span class="orbit-star" aria-hidden="true"></span><div class="photo-caption"><strong>Rooted in Paco. Moving together.</strong><span>Our volunteers, out in the community.</span></div><div class="photo-note">${icon('people')}<div><strong>A little time. A lasting difference.</strong><small>Every act of service has a place here.</small></div></div></div></div></section>
  <div class="marquee" aria-label="Our values"><span>Volunteer with purpose</span><b aria-hidden="true">✳</b><span>Lead with integrity</span><b aria-hidden="true">✳</b><span>Grow together</span><b aria-hidden="true">✳</b><span>Serve the community</span></div>
  <div class="container"><div class="intro-strip"><h2>Local roots.<br>Collective strength.</h2><p>Lakas Kabataan ng Paco is a community-based youth organization in Obando, Bulacan. Through volunteerism and active leadership, we turn the energy of young people into meaningful action for our neighbors.</p></div></div>
  <section class="section"><div class="container"><div class="section-title"><div><div class="eyebrow">Our impact, in perspective</div><h2>Small actions.<br>Shared progress.</h2></div><a href="#impact" class="text-link">Explore our impact ↗</a></div>${stats()}<p class="fine spacer">Source: supplied annual accomplishment report. Counts describe individual activities and are not a total of unique beneficiaries.</p></div></section>
  <section class="section soft-section"><div class="container"><div class="section-title"><div><div class="eyebrow">From plans to purpose</div><h2>This is what showing up looks like.</h2></div><a class="text-link" href="#projects">All projects ↗</a></div><div class="cards">${['p6','p5','p4'].map(i=>card(data.projects.find(p=>p.id===i)||SEED.projects.find(p=>p.id===i))).join('')}</div></div></section>
  <section class="section"><div class="container"><div class="section-title"><div><div class="eyebrow">Where we put our energy</div><h2>Many ways to make a difference.</h2></div><p class="muted">Four program priorities. One commitment to the welfare of our community.</p></div>${pillars()}</div></section>
  <section class="section soft-section"><div class="container split"><div><div class="eyebrow">Built on trust</div><h2>Every contribution.<br>Open to everyone.</h2><p class="muted">See how resources can support community work through our public income and expense ledger.</p><p class="fine">The financial dashboard currently uses illustrative figures. Verified totals and supporting receipts will be added by LKP.</p><a href="#transparency" class="button">Explore transparency ${icon('arrow')}</a></div><div class="ledger-preview"><div class="project-meta"><span class="eyebrow" style="margin:0">Community fund</span><span class="badge gold">Sample figures</span></div><div class="row"><span>Total contributions</span><strong>${money(f.income)}</strong></div><div class="row"><span>Program expenses</span><strong>${money(f.expense)}</strong></div><div class="row" style="border:0"><span>Available balance</span><strong class="total">${money(f.balance)}</strong></div><p class="fine" style="margin:10px 0 0">Illustrative ledger · editable in the officer demo</p></div></div></section>
  <section class="section"><div class="container"><div class="section-title"><div><div class="eyebrow">On the community board</div><h2>Good things to know.</h2></div><a class="text-link" href="#announcements">All announcements ↗</a></div><div class="news-list">${data.announcements.slice(0,3).map(a=>`<article class="news-item"><time>${date(a.date)}</time><div><h3>${esc(a.title)}</h3><p>${esc(a.body.slice(0,160))}${a.sample?' · Sample announcement':''}</p></div><button class="circle-link" data-action="announcement" data-id="${esc(a.id)}" aria-label="Read ${esc(a.title)}">↗</button></article>`).join('')||'<p class="empty">No announcements yet.</p>'}</div></div></section>
  <section class="section" style="padding-top:0"><div class="container"><div class="cta"><div><div class="eyebrow">Your community needs your kind of energy</div><h2>Be the reason<br>something good happens.</h2><p>Give your time, share your skills, or support a cause.</p></div><a class="button" href="#volunteer">Become a volunteer ${icon('arrow')}</a></div></div></section>`;}
function projects(){return heading('Our work','Youth-led. Community-felt.','Explore completed activities and the FY 2026 plans. Planned dates are retained as supplied; completion is not assumed.')+`<section class="section container" style="padding-top:0"><div class="toolbar"><div class="filters" aria-label="Project status">${['All','Conducted','Planned','Proposed'].map(x=>`<button class="chip ${projectFilter===x?'active':''}" aria-pressed="${projectFilter===x}" data-action="filter-projects" data-value="${x}">${x}</button>`).join('')}</div><label class="sr-only" for="project-search">Search projects</label><input id="project-search" class="search" placeholder="Search a project or cause…" value="${esc(projectQuery)}" type="search"></div><div class="cards" id="project-results">${projectResults()}</div><p class="fine spacer">The supplied file is named FY25 but contains activities through February 2026. Each project shows its recorded date. <a class="text-link" href="assets/annual-report.pdf" target="_blank" rel="noopener">Read the source report ↗</a></p></section>`;}
function projectResults(){const list=data.projects.filter(p=>(projectFilter==='All'||p.status===projectFilter)&&`${p.title} ${p.category} ${p.summary}`.toLowerCase().includes(projectQuery.toLowerCase()));return list.map(card).join('')||'<div class="empty">No matching projects. Try another filter or search. Officers can add a proposed project in the demo portal.</div>';}
function impact(){return heading('Our impact','Progress you can trace.','People, places, and causes behind the work. We show the evidence we have and leave room for better measurement.')+`<section class="section dark-section"><div class="container">${stats()}</div></section><section class="section container"><div class="two-col"><div><div class="eyebrow">People behind the numbers</div><h2>A total is only useful<br>when it is reliable.</h2><p class="muted">A consolidated count of unique beneficiaries is not yet available. Activity-level attendance can include the same people more than once. Animal beneficiaries are tracked separately.</p>${notice('Impact tracker mockup: future reports can add deduplicated beneficiaries, volunteer hours, households reached, and progress toward project targets.')}</div><div class="panel"><h3>What the report tells us</h3><div class="ledger-preview" style="transform:none;border:0;padding:0;box-shadow:none"><div class="row"><span>First aid & water assistance</span><strong>100+ spectators</strong></div><div class="row"><span>Voter registration seminar</span><strong>51 students</strong></div><div class="row"><span>Brigada Eskwela</span><strong>Count needs clarification</strong></div><div class="row"><span>Animal feeding activities</span><strong>2 documented rounds</strong></div><div class="row"><span>Total unique beneficiaries</span><strong>Not consolidated</strong></div></div><p class="fine spacer">Brigada Eskwela lists “2 Teachers / Students.” No total animal count or volunteer hours were supplied.</p></div></div><div class="spacer">${pillars()}</div><div class="actions spacer"><a class="button" href="assets/annual-report.pdf" target="_blank" rel="noopener">Read our accomplishment report ↗</a><a class="text-link" href="#volunteer">Help shape our next chapter ↗</a></div></section>`;}
function financeStats(){const f=finance();return `<div class="finance-stats">${[['Total income',f.income],['Total expenses',f.expense],['Available balance',f.balance]].map(([label,amount])=>`<div class="finance-stat"><span>${label} · SAMPLE</span><strong>${money(amount)}</strong></div>`).join('')}</div>`;}
function ledger(edit=false){let rows=data.transactions.filter(t=>financeFilter==='All'||t.type===financeFilter).slice().sort((a,b)=>b.date.localeCompare(a.date));return `<div class="table-wrap"><table><caption class="sr-only">Illustrative community income and expenses in Philippine pesos</caption><thead><tr><th>Date</th><th>Project / description</th><th>Type</th><th class="amount">Amount (PHP)</th>${edit?'<th>Manage</th>':'<th>Evidence</th>'}</tr></thead><tbody>${rows.map(t=>`<tr><td>${date(t.date)}</td><td><strong>${esc(t.project)}</strong><br><span class="muted">${esc(t.description)}</span></td><td><span class="badge ${t.type==='Expense'?'gold':''}">${esc(t.type)}</span></td><td class="amount">${money(t.amount)}</td><td>${edit?`<button class="chip" data-action="edit-transaction" data-id="${esc(t.id)}">Edit</button>`:'<span class="fine">Demo · no receipt</span>'}</td></tr>`).join('')||'<tr><td colspan="5">No transactions for this filter.</td></tr>'}</tbody></table></div>`;}
function transparency(){return heading('Transparency','Trust, in every transaction.','A clear view of how resources come in and how they support our work.')+`<section class="section container" style="padding-top:0">${notice('<strong>Illustrative financial report.</strong> Every peso figure below is mock data, including amounts assigned to planned projects. It is not LKP’s official financial position. The supplied report states 20% fundraising allocations but provides no peso totals.')}${financeStats()}<div class="toolbar"><div class="filters">${['All','Income','Expense'].map(x=>`<button class="chip ${financeFilter===x?'active':''}" aria-pressed="${financeFilter===x}" data-action="filter-finance" data-value="${x}">${x}</button>`).join('')}</div><button class="button outline small" data-action="export-csv">Download sample CSV ↓</button></div>${ledger()}<div class="two-col spacer"><div class="panel"><div class="eyebrow">Our accountability process</div><h3>A record behind every expense.</h3><p class="muted">The live version should link each approved expense to a redacted receipt, project, reviewer, and publication date.</p><p class="fine">Treasurer: Jim Russel M. Dela Cruz<br>Auditor: Al Emmanuel J. Nolido</p></div><div class="panel"><div class="eyebrow">Reports & documents</div><h3>Start with the source.</h3><p class="muted">Read the supplied accomplishment report and organization registration certificate.</p><div class="actions"><a class="text-link" href="assets/annual-report.pdf" target="_blank" rel="noopener">Annual report ↗</a><a class="text-link" href="assets/nyc-certificate.pdf" target="_blank" rel="noopener">NYC registration ↗</a></div></div></div></section>`;}
function about(){return heading('About LKP','The strength of youth.<br>The heart of a community.','We are Lakas Kabataan ng Paco, a community-based organization registered with the National Youth Commission, serving Barangay Paco in Obando, Bulacan.')+`<section class="section container" style="padding-top:0"><div class="two-col"><article class="panel"><div class="eyebrow">Our vision</div><h2 style="font-size:32px">A generation that leads<br>with integrity.</h2><p class="muted">${esc(ORGANIZATION.vision)}</p></article><article class="panel"><div class="eyebrow">Our mission</div><h2 style="font-size:32px">Empowered youth.<br>Lasting community action.</h2><p class="muted">${esc(ORGANIZATION.mission)}</p></article></div></section><section class="section soft-section"><div class="container split"><div><div class="eyebrow">Our goals</div><h2>Purpose in every step.</h2><div class="goals">${GOALS.map(([t,p])=>`<div class="goal"><div><h3>${t}</h3><p>${p}</p></div></div>`).join('')}</div></div><img src="assets/green-paco.jpg" alt="LKP volunteers collecting litter during Green Paco" loading="lazy" style="border-radius:12px;width:100%;height:570px;object-fit:cover"></div></section><section class="section container"><div class="section-title"><div><div class="eyebrow">Meet the people who show up</div><h2>Our officers.</h2></div><p class="muted">A shared commitment to service, responsibility, and a stronger Paco.</p></div><div class="officers">${OFFICERS.map(([name,role])=>`<article class="officer"><div class="avatar" aria-hidden="true">${initials(name)}</div><h3>${esc(name)}</h3><p>${esc(role)}</p></article>`).join('')}</div><p class="fine spacer">Officer names and roles supplied by LKP. Add approved portraits and term dates when available.</p></section><section class="section soft-section"><div class="container split"><div><div class="eyebrow">Our registration & certificates</div><h2>Community-rooted.<br>Officially registered.</h2><p>National Youth Commission<br><strong>Community-Based Organization</strong></p><p class="muted">URN: ${ORGANIZATION.urn}<br>Issued: ${ORGANIZATION.issued}</p><p class="fine">The certificate states validity for three years from issuance, subject to compliance and possible suspension or revocation. The document is shown as supplied; this site does not independently verify current standing.</p><a class="button" href="assets/nyc-certificate.pdf" target="_blank" rel="noopener">View registration certificate ↗</a><p class="fine spacer">Additional organization certificates can be added here. Individual member certificates appear privately in the member portal.</p></div><a href="assets/nyc-certificate.pdf" target="_blank" rel="noopener" aria-label="Open NYC registration certificate PDF"><img class="certificate-img" src="assets/nyc-certificate.png" alt="NYC certificate of registration for Lakas Kabataan ng Paco, issued July 14, 2025" loading="lazy"></a></div></section><section class="section container"><div class="panel"><div class="eyebrow">Made for our community</div><h3>A website with room to grow.</h3><p class="muted">This editable mockup was prepared with OpenAI Codex for LKP. Final developer attribution: <strong>${esc(ORGANIZATION.developer)}</strong>.</p><a class="text-link" href="#developer">Development credits & next steps ↗</a></div></section>`;}
function volunteer(){return heading('Become a volunteer','Your time can change<br>someone’s day.','Bring your energy, skills, and heart. Tell us where you would like to contribute.')+`<section class="section container" style="padding-top:0"><div class="split" style="align-items:start"><aside><img src="assets/community.jpg" alt="LKP volunteers together during a community activity" style="border-radius:12px;width:100%;height:310px;object-fit:cover"><h3 class="spacer">There is a place for you here.</h3><ol class="steps"><li>Share your interests through the application.</li><li>An officer reviews your application and availability.</li><li>Join an orientation and find your first activity.</li></ol><p class="fine">The process above is a proposed volunteer flow. Final eligibility and safeguarding arrangements will be confirmed by LKP.</p></aside><div class="panel">${notice('Demo application only. Use fictional details. This form saves in this browser; it does not send an application to LKP.')}<form id="volunteer-form" class="form-grid"><div class="field"><label for="v-name">Full name *</label><input id="v-name" name="name" required maxlength="100" autocomplete="off"></div><div class="field"><label for="v-email">Email *</label><input id="v-email" name="email" type="email" required maxlength="150" autocomplete="off"></div><div class="field"><label for="v-age">Age group *</label><select id="v-age" name="age" required><option value="">Select an age group</option><option>Under 18</option><option>18–24</option><option>25–30</option><option>31 or above</option></select></div><div class="field"><label for="v-interest">Area of interest *</label><select id="v-interest" name="interest" required><option value="">Choose a cause</option>${['Health','Environment','Sports','Education & leadership','Animal welfare','Creative & communications','General volunteering'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field full"><label for="v-availability">Availability *</label><input id="v-availability" name="availability" required maxlength="200" placeholder="e.g. Weekends, 2–4 hours a month"></div><div class="field full"><label for="v-skills">Skills or motivation</label><textarea id="v-skills" name="skills" maxlength="1500" placeholder="Tell us what you would love to contribute."></textarea></div><div class="field full"><label class="check"><input type="checkbox" required name="consent">I understand this is a browser-only demo and will use fictional information.</label><p class="fine">For applicants under 18, a live service would need an approved guardian consent and safeguarding process. No guardian data is collected here.</p><button class="button" type="submit">Save demo application ${icon('arrow')}</button><div class="form-error" role="alert"></div></div></form></div></div></section>`;}
function donate(){return heading('Support our work','Give a little.<br>Help something good grow.','Time, supplies, and community support keep youth-led service moving.')+`<section class="section container" style="padding-top:0">${notice('<strong>Donation details are placeholders.</strong> The supplied number 0900000000 is not a verified payment destination. No live payment or donation collection is enabled.')}<div class="two-col"><article class="panel"><div class="eyebrow">Monetary support</div>${icon('heart')}<h2 class="spacer" style="font-size:36px">Support via GCash.</h2><div class="donation-number">${esc(ORGANIZATION.gcash)}</div><span class="badge gold">Placeholder · do not send funds</span><p class="muted spacer">Before launch, LKP will confirm the account holder, correct number, verified QR code, acknowledgment process, and authorized fundraising arrangements.</p><button class="button outline" disabled>GCash details awaiting verification</button></article><article class="panel"><div class="eyebrow">In-kind support</div>${icon('people')}<h2 class="spacer" style="font-size:36px">Useful things.<br>Meaningful change.</h2><p class="muted">Coordinate with our contact person about the supplies needed for each project, drop-off arrangements, and accepted items.</p><p><strong>${esc(ORGANIZATION.contact)}</strong><br>${esc(ORGANIZATION.phone)} <span class="fine">(placeholder)</span></p><a class="button" href="#contact">See contact & donation FAQs ↗</a></article></div><div class="split spacer"><div class="panel"><h3>What your support could help provide</h3><ul><li>Community program supplies</li><li>Volunteer materials and logistics</li><li>Sports and education resources</li><li>Animal feeding supplies</li></ul><p class="fine">These are examples of support needs, not active collection requests.</p></div><div><div class="eyebrow">Accountability is part of giving</div><h2 style="font-size:36px">See where support goes.</h2><p class="muted">Our transparency section previews the public reports we plan to maintain.</p><a class="text-link" href="#transparency">Visit the transparency hub ↗</a></div></div></section>`;}
function suggestions(){return heading('Your voice matters','A better Paco starts<br>with a shared idea.','Suggest a project, offer feedback, or share an idea for our community.')+`<section class="section container" style="padding-top:0"><div class="two-col" style="align-items:start"><div class="panel"><h3>What would you like to see?</h3>${notice('Demo only. Use fictional details. Your idea stays in this browser and appears publicly here after approval in the officer demo.')}<form id="suggestion-form"><div class="field"><label for="s-name">Display name *</label><input id="s-name" name="name" required maxlength="80" placeholder="e.g. A Paco volunteer"></div><div class="field spacer"><label for="s-title">Idea title *</label><input id="s-title" name="title" required maxlength="120"></div><div class="field spacer"><label for="s-body">Suggestion or comment *</label><textarea id="s-body" name="body" required minlength="10" maxlength="2000"></textarea></div><label class="check spacer"><input type="checkbox" required>I agree to respectful discussion and understand this is a local demo.</label><button class="button spacer">Submit demo suggestion ↗</button><div class="form-error" role="alert"></div></form></div><div><h3>Community ideas</h3><p class="fine">Only approved suggestions are displayed. Please avoid personal details in public comments.</p>${data.suggestions.filter(s=>s.status==='Approved').map(s=>`<article class="suggestion"><span class="badge">Community idea · demo</span><h3 class="spacer">${esc(s.title)}</h3><p>${esc(s.body)}</p><small>Shared by ${esc(s.name)} · ${date(s.date)}</small></article>`).join('')||'<div class="empty">No approved ideas yet.<br>Be the first to share a suggestion.</div>'}</div></div></section>`;}
function announcements(){return heading('Community board','Updates from LKP.','Announcements, volunteer opportunities, and news from our organization.')+`<section class="section container" style="padding-top:0"><div class="news-list">${data.announcements.map(a=>`<article class="news-item"><time>${date(a.date)}</time><div><h3>${esc(a.title)}</h3><p class="preline">${esc(a.body)}</p>${a.sample?'<span class="badge gold spacer">Demo announcement</span>':''}</div><span aria-hidden="true">↗</span></article>`).join('')||'<p class="empty">No announcements yet.</p>'}</div></section>`;}
function contact(){return heading('Contact & FAQs','Let’s build this together.','Questions about volunteering, partnerships, or supporting a community project? Start here.')+`<section class="section container" style="padding-top:0"><div class="two-col"><div class="panel"><h3>Community contact</h3><p>${ORGANIZATION.location}<br>Philippines</p><p>In-kind donation coordination:<br><strong>${ORGANIZATION.contact}</strong><br>${ORGANIZATION.phone} <span class="fine">(placeholder)</span></p>${notice('Official email, social links, operating hours, and a verified contact number have not been supplied. Live contact links will be added after confirmation.')}<div class="actions"><a class="text-link" href="#volunteer">Volunteer application ↗</a><a class="text-link" href="#suggestions">Share feedback ↗</a></div></div><div><h3>Frequently asked questions</h3>${[['Who can volunteer?','Aspiring volunteers can express interest through the mock application. LKP still needs to confirm membership criteria, age requirements, and the guardian consent process for minors.'],['How do I get a member account?','In the proposed live workflow, officers review applications before approving membership. This mockup provides fixed sample accounts so you can explore the dashboards.'],['Where can I find my certificates?','Use the member portal. Certificates shown there are assigned to the signed-in demo member and clearly labeled samples. Real certificate files will require private storage.'],['Can I donate now?','Donation collection is disabled in this mockup. The provided contact and GCash numbers are placeholders and must be verified before use.'],['Are the financial figures real?','No. All peso amounts are illustrative and editable in the officer demo. The project histories and report-level activity counts come from the supplied annual report.'],['Is the website already connected to LKP?','No. Demo submissions and officer changes stay in your browser. There is no live database, email delivery, or payment integration.']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div></div></section>`;}
function privacy(){return heading('Privacy & demo notice','A clear boundary<br>for this first version.')+`<section class="section container text-body" style="padding-top:0"><p>This is an editable mockup, not a live membership service. Use fictional data in every form.</p><h2>What this demo stores</h2><p>Applications, suggestions, sample member records, certificates, announcements, projects, and transactions are stored in this browser’s localStorage under <code>${STORE_KEY}</code>. They are not submitted to LKP or an external database. Anyone using this browser profile can inspect or reset that data.</p><p>The demo login is kept in memory and ends on refresh. Demo passwords are publicly visible in the JavaScript source. They do not protect real records.</p><h2>What is not connected</h2><p>No analytics, email service, payment gateway, database, live authentication, or third-party font service is configured. This package includes local logo, photos, and supplied PDFs.</p><h2>Resetting the demo</h2><p>Use “Reset demo” at the top to remove this mockup’s saved browser data and restore its sample records. It does not remove other websites’ data.</p><h2>Before a public launch</h2><p>LKP should approve a privacy notice identifying its contact person, purposes, access controls, retention periods, member rights, guardian consent process, and publication consent for photos. Private certificates and applicant details should use server-enforced access controls.</p><a class="button" href="#home">Back to LKP</a></section>`;}
function developer(){return heading('Behind the website','Built for the next<br>chapter of LKP.')+`<section class="section container text-body" style="padding-top:0"><div class="panel"><div class="eyebrow">Developer credits</div><h3>${esc(ORGANIZATION.developer)}</h3><p>Editable design and interactive prototype prepared with OpenAI Codex for Lakas Kabataan ng Paco. Replace the placeholder with the approved developer name, portfolio, and contribution details.</p><p class="fine">Organization copy and officer information: supplied by LKP.<br>Project source: supplied annual accomplishment report.<br>Logo, photos, and registration certificate: supplied local LKP files.<br>Function reference: Angat Buhay’s public program, impact, and involvement sections; visual design created independently for LKP.</p></div><h2>Useful additions for the live website</h2><ul><li>Project calendar with reminders and volunteer capacity limits</li><li>Attendance tracking and verified volunteer hours</li><li>Private certificate downloads and optional consent-based verification codes</li><li>Receipt attachments with a treasurer-to-auditor approval process</li><li>Partnership inquiries and project wish lists</li><li>English / Filipino content and accessible media captions</li></ul><a class="text-link" href="#about">Back to our organization ↗</a></section>`;}
function login(){return heading('Member & officer portal','Your place in the movement.','A dedicated space for your membership, service, and certificates.')+`<section class="section container" style="padding-top:0"><div class="login-wrap panel"><h3>Log in to the demo</h3><p class="fine">This simulates username and password login. It does not secure real member information.</p><div class="credentials"><strong>Sample member</strong> · member.lkp<br><strong>Sample officer</strong> · officer.lkp<br><strong>Password for both</strong> · LKPdemo2026!</div><form id="login-form"><div class="field spacer"><label for="username">Username</label><input id="username" name="username" required autocomplete="off" autocapitalize="none"></div><div class="field spacer"><label for="password">Password</label><input id="password" name="password" type="password" required autocomplete="off"></div><div class="form-error" role="alert"></div><button class="button" style="width:100%">Log in ↗</button></form><p class="fine spacer">Need to join? <a class="text-link" href="#volunteer">Apply as a volunteer</a></p><p class="fine">Password recovery and new account creation will be enabled when live authentication is connected.</p></div></section>`;}
function certCard(c){return `<article class="cert-card"><span class="badge gold">Sample certificate</span><h3>${esc(c.title)}</h3><p>${esc(c.project)}<br>Issued ${date(c.date)}<br>Reference: ${esc(c.reference)}</p><button class="button outline small" data-action="certificate" data-id="${esc(c.id)}">Preview & download sample ↗</button></article>`;}
function dashboard(){if(!session)return login();const officer=session.role==='officer';const member=data.members.find(m=>m.id===session.id);const tabs=officer?['overview','announcements','projects','finances','applications','members','certificates','suggestions','activity log']:['overview','certificates','profile'];if(!tabs.includes(portalTab))portalTab='overview';return `<section class="section container"><div class="dashboard-header"><div><div class="eyebrow">${officer?'Officer workspace':'Member portal'} · Demo</div><h1>Welcome, ${esc(session.name.split(' ')[0])}.</h1><p class="muted" style="margin:0">${officer?'Keep our community informed and our work accountable.':'Your service, your progress, your community.'}</p></div><button class="button outline small" data-action="logout">Log out ↗</button></div>${notice('Browser-only demo workspace. Changes affect this browser’s mockup. No live account, official certificate, or public LKP record is created.')}<div class="tabs" aria-label="Dashboard sections">${tabs.map(t=>`<button class="${portalTab===t?'active':''}" aria-pressed="${portalTab===t}" data-action="portal-tab" data-value="${t}">${t[0].toUpperCase()+t.slice(1)}${t==='applications'&&data.applications.filter(a=>a.status==='Pending').length?` (${data.applications.filter(a=>a.status==='Pending').length})`:''}</button>`).join('')}</div>${officer?officerContent():memberContent(member)}</section>`;}
function memberContent(m){const certs=data.certificates.filter(c=>c.memberId===session.id);if(portalTab==='certificates')return `<h3>Your certificates</h3><p class="fine">Visible to this sample member in the demo. Live privacy must be enforced by the database.</p><div class="two-col">${certs.map(certCard).join('')||'<div class="empty">No certificates assigned yet.</div>'}</div>`;if(portalTab==='profile')return `<div class="panel text-body"><span class="badge gold">Fictional member</span><h3 class="spacer">${esc(m.name)}</h3><p>Member ID: DEMO-${esc(m.id)}<br>Username: ${esc(m.username)}<br>Status: ${esc(m.status)}</p><p class="fine">Profile changes and account settings are reserved for the future live service. Ask an officer for membership updates.</p></div>`;return `<div class="dashboard-stats"><div class="panel"><strong>${esc(m.status)}</strong><span>Sample membership status</span></div><div class="panel"><strong>${m.hours}</strong><span>Illustrative volunteer hours</span></div><div class="panel"><strong>${certs.length}</strong><span>Sample certificates assigned to you</span></div></div><div class="two-col"><div class="panel"><h3>Your next step</h3><p class="muted">Discover a cause that matters to you and follow the community board for new opportunities.</p><div class="actions"><a class="button small" href="#projects">Explore projects ↗</a><a class="text-link" href="#announcements">Read updates ↗</a></div></div><div class="panel"><h3>Recognition for showing up.</h3><p class="muted">Find and preview the certificates assigned to your sample profile.</p><button class="button outline small" data-action="portal-tab" data-value="certificates">View my certificates ↗</button></div></div>`;}
function officerContent(){switch(portalTab){
case 'announcements':return `<div class="toolbar"><h3>Announcements</h3><button class="button small" data-action="new-announcement">New announcement +</button></div>${data.announcements.map(a=>`<div class="panel spacer"><span class="badge gold">Demo</span><h3 class="spacer">${esc(a.title)}</h3><p class="preline">${esc(a.body)}</p><div class="actions"><span class="fine">${date(a.date)}</span><button class="chip" data-action="edit-announcement" data-id="${esc(a.id)}">Edit</button></div></div>`).join('')}`;
case 'projects':return `<div class="toolbar"><h3>Project records</h3><button class="button small" data-action="new-project">Add project +</button></div><p class="fine">Project records load from MongoDB. Create, edit, and delete operations use the Express API.</p><div class="table-wrap"><table><thead><tr><th>Project</th><th>Status</th><th>Date</th><th>Manage</th></tr></thead><tbody>${data.projects.map(p=>`<tr><td>${esc(p.title)}${p.sample?' · DEMO':''}</td><td>${esc(p.status)}</td><td>${date(p.date)}</td><td><button class="chip" data-action="edit-project" data-id="${esc(p.id)}">Edit</button> <button class="chip" data-action="delete-project" data-id="${esc(p.id)}">Delete</button></td></tr>`).join('')}</tbody></table></div>`;
case 'finances':return `<div class="toolbar"><h3>Illustrative financial ledger</h3><div class="actions"><button class="button outline small" data-action="export-csv">Export sample CSV ↓</button><button class="button small" data-action="new-transaction">Add transaction +</button></div></div>${financeStats()}${ledger(true)}`;
case 'applications':return `<h3>Volunteer applications</h3><p class="fine">Approval changes the demo application status. It does not create an account or send an email.</p>${data.applications.map(a=>`<article class="panel spacer"><span class="badge ${a.status==='Pending'?'gold':''}">${esc(a.status)}</span><h3 class="spacer">${esc(a.name)}</h3><p>${esc(a.email)} · ${esc(a.age)}<br>Interest: ${esc(a.interest)}<br>Availability: ${esc(a.availability)}</p><p class="preline">${esc(a.skills)}</p>${a.age==='Under 18'?notice('Under-18 application: guardian consent and officer safeguarding review would be required before live participation.'):''}${a.status==='Pending'?`<div class="actions"><button class="button small" data-action="application-status" data-id="${esc(a.id)}" data-value="Approved">Approve demo application</button><button class="button outline small" data-action="application-status" data-id="${esc(a.id)}" data-value="Declined">Decline</button></div>`:''}</article>`).join('')||'<div class="empty">No demo applications yet. Submit one from the volunteer page.</div>'}`;
case 'members':return `<h3>Sample member directory</h3><p class="fine">All names and service hours here are fictional. Updates are local to this browser.</p><div class="two-col">${data.members.map(m=>`<form class="panel" data-member-form="${esc(m.id)}"><h3>${esc(m.name)}</h3><p class="fine">${esc(m.username)} · DEMO-${esc(m.id)}</p><div class="field"><label for="status-${esc(m.id)}">Membership status</label><select id="status-${esc(m.id)}" name="status">${['Pending','Active','Inactive'].map(s=>`<option ${m.status===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="field spacer"><label for="hours-${esc(m.id)}">Illustrative volunteer hours</label><input id="hours-${esc(m.id)}" name="hours" type="number" min="0" max="100000" step="0.5" value="${m.hours}" required></div><button class="button small spacer">Update sample member</button><div class="form-error" role="alert"></div></form>`).join('')}</div>`;
case 'certificates':return `<div class="toolbar"><h3>Member certificates</h3><button class="button small" data-action="new-certificate">Assign sample certificate +</button></div><div class="two-col">${data.certificates.map(c=>`<div><p class="fine">Assigned to: ${esc(data.members.find(m=>m.id===c.memberId)?.name||'Unknown member')}</p>${certCard(c)}</div>`).join('')}</div>`;
case 'suggestions':return `<h3>Suggestion moderation</h3>${data.suggestions.map(s=>`<article class="panel spacer"><span class="badge ${s.status==='Pending'?'gold':''}">${esc(s.status)}</span><h3 class="spacer">${esc(s.title)}</h3><p class="preline">${esc(s.body)}</p><p class="fine">${esc(s.name)} · ${date(s.date)}</p><div class="actions">${s.status!=='Approved'?`<button class="button small" data-action="suggestion-status" data-id="${esc(s.id)}" data-value="Approved">Approve for demo board</button>`:''}${s.status!=='Hidden'?`<button class="button outline small" data-action="suggestion-status" data-id="${esc(s.id)}" data-value="Hidden">Hide</button>`:''}</div></article>`).join('')||'<div class="empty">No suggestions awaiting review.</div>'}`;
case 'activity log':return `<div class="toolbar"><h3>Demo activity log</h3><button class="button outline small" data-action="export-json">Download demo backup ↓</button></div><p class="fine">This editable browser log demonstrates traceability. It is not an immutable audit trail.</p><ol class="audit">${data.audit.slice(0,100).map(a=>`<li><strong>${esc(a.action)}</strong><br><span class="muted">${esc(a.actor)} · ${esc(new Date(a.date).toLocaleString('en-PH'))}</span></li>`).join('')||'<li>No changes recorded yet.</li>'}</ol>`;
default:return `<div class="dashboard-stats"><div class="panel"><strong>${data.projects.length}</strong><span>Project records</span></div><div class="panel"><strong>${data.applications.filter(a=>a.status==='Pending').length}</strong><span>Pending demo applications</span></div><div class="panel"><strong>${data.suggestions.filter(s=>s.status==='Pending').length}</strong><span>Suggestions to review</span></div></div><div class="two-col"><div class="panel"><h3>Bring the community up to date.</h3><p class="muted">Share an announcement, document a project, or update the illustrative ledger.</p><div class="actions"><button class="button small" data-action="new-announcement">Post an announcement +</button><button class="button outline small" data-action="new-project">Add a project +</button></div></div><div class="panel"><h3>Before this goes live</h3><p class="muted">Confirm payment details, project statuses, financial records, privacy arrangements, and officer access.</p><p class="fine">The included SETUP.md explains the proposed Supabase + Cloudflare deployment path.</p><a class="text-link" href="#transparency">View public transparency page ↗</a></div></div>`;}}
const routes={home,projects,impact,transparency,about,volunteer,donate,suggestions,announcements,contact,privacy,developer,portal:dashboard};
function render(scroll=true){const route=location.hash.slice(1)||'home';const page=routes[route]||home;main.innerHTML=page();document.title=`${route==='home'?'Youth-led community action':route==='portal'?'Member & officer portal':route[0].toUpperCase()+route.slice(1)} | Lakas Kabataan ng Paco`;document.querySelectorAll('nav a').forEach(a=>{if(a.hash==='#'+route)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});document.querySelector('nav').classList.remove('open');document.querySelector('.menu-toggle').setAttribute('aria-expanded','false');if(scroll){window.scrollTo(0,0);main.focus({preventScroll:true});}}
function showProject(pid){const p=data.projects.find(x=>x.id===pid);if(!p)return;openModal(`<div class="eyebrow">${esc(p.category)} · ${esc(p.status)}</div><h2 id="modal-title">${esc(p.title)}</h2>${p.image?`<img class="modal-photo" src="${esc(p.image)}" alt="LKP ${esc(p.category)} community activity">`:''}<p>${esc(p.summary)}</p><div class="detail-grid"><div><span>Recorded / planned date</span><strong>${date(p.date)}</strong></div><div><span>Location</span><strong>${esc(p.location)}</strong></div><div><span>Reported reach / allocation</span><strong>${esc(p.reach)}</strong></div><div><span>Source</span><strong>${esc(p.source)}</strong></div></div><p class="muted">${esc(p.result)}</p>${p.status==='Planned'?notice('The planned date has passed. Completion has not been confirmed.'):''}${p.sample?notice('Demo record edited or created in this browser. Consult the original report for verified history.'):''}<a class="button outline" href="assets/annual-report.pdf" target="_blank" rel="noopener">Read supplied report ↗</a>`);}
function requireOfficer(){if(session?.role!=='officer'){toast('Use the officer demo account to access this action.');return false;}return true;}
function formField(name,label,value='',type='text',full=false,extra=''){return `<div class="field ${full?'full':''}"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" value="${esc(value)}" type="${type}" required ${extra}></div>`;}
function textField(name,label,value='',full=true){return `<div class="field ${full?'full':''}"><label for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}" required maxlength="3000">${esc(value)}</textarea></div>`;}
function selectField(name,label,options,value=''){return `<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${options.map(x=>`<option ${value===x?'selected':''}>${esc(x)}</option>`).join('')}</select></div>`;}
function editor(kind,recordId){if(!requireOfficer())return;let r={},fields='',title='';if(kind==='announcement'){r=data.announcements.find(x=>x.id===recordId)||{};title='announcement';fields=formField('title','Title',r.title||'','text',true,'maxlength="150"')+formField('date','Publication date',r.date||today(),'date',true)+textField('body','Announcement',r.body||'');}if(kind==='project'){r=data.projects.find(x=>x.id===recordId)||{};title='project';fields=formField('title','Project title',r.title||'','text',true,'maxlength="150"')+selectField('category','Cause',['Health','Environment','Sports','Education','Leadership','Animal welfare','Fundraising'],r.category)+selectField('status','Project status',['Proposed','Planned','Conducted'],r.status||'Proposed')+formField('date','Project date',r.date||today(),'date')+formField('location','Location',r.location||'To be confirmed')+formField('reach','Reported reach / target',r.reach||'Not yet recorded','text',true)+textField('summary','Short description',r.summary||'')+textField('result','Results / current status',r.result||'Results to be confirmed.');}if(kind==='transaction'){r=data.transactions.find(x=>x.id===recordId)||{};title='sample transaction';fields=formField('date','Date',r.date||today(),'date')+selectField('type','Transaction type',['Income','Expense'],r.type)+formField('project','Project / fund',r.project||'')+formField('amount','Amount (PHP)',r.amount||'','number',false,'min="0.01" max="100000000" step="0.01"')+formField('description','Description',r.description||'','text',true,'maxlength="300"');}if(kind==='certificate'){title='sample certificate';fields=`<div class="field full"><label for="f-memberId">Assign to sample member</label><select name="memberId" id="f-memberId">${data.members.map(m=>`<option value="${esc(m.id)}">${esc(m.name)}</option>`).join('')}</select></div>`+formField('title','Certificate title','','text',true,'maxlength="150"')+formField('project','Project / recognition','','text',true,'maxlength="150"')+formField('date','Issue date',today(),'date',true);}
openModal(`<h2 id="modal-title">${recordId?'Edit':'Add'} ${title}</h2><p class="fine">${kind==='project'?'Project data is saved in MongoDB through the Express API.':'Demo changes are saved in this browser only.'}</p><form data-editor="${kind}" data-id="${esc(recordId||'')}" class="form-grid">${fields}<div class="field full"><div class="form-error" role="alert"></div><button class="button" type="submit">Save ${title}</button></div></form>`);}
function download(content,filename,type){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000);}
function csvCell(value){let s=String(value??'');if(/^[\s]*[=+@-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';}
function exportCSV(){const rows=[['SAMPLE DATA ONLY - NOT AN OFFICIAL LKP REPORT'],['Date','Project','Description','Type','Amount PHP'],...data.transactions.map(t=>[t.date,t.project,t.description,t.type,t.amount.toFixed(2)])];download('\uFEFF'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n'),'LKP-SAMPLE-ledger.csv','text/csv;charset=utf-8');}
function certificate(cid,downloadFile=false){const c=data.certificates.find(x=>x.id===cid);if(!session||!c||(session.role!=='officer'&&c.memberId!==session.id)){toast('This certificate is not assigned to your demo profile.');return;}const m=data.members.find(x=>x.id===c.memberId);if(!m)return;const content=`<div style="border:3px solid #205d50;padding:30px;text-align:center;font-family:Georgia,serif;color:#18382f"><p style="color:#946a00;letter-spacing:3px">SAMPLE — NOT AN OFFICIAL CERTIFICATE</p><h2 id="modal-title">${esc(c.title)}</h2><p>Lakas Kabataan ng Paco</p><p>Presented in this mockup to</p><h1 style="font-size:34px">${esc(m.name)}</h1><p>For illustrative service in</p><h3>${esc(c.project)}</h3><p>${date(c.date)}</p><small>${esc(c.reference)} · Demo reference only</small><p style="font-size:12px">No official signature, verification, or accreditation is implied.</p></div>`;if(downloadFile){download(`<!doctype html><html lang="en"><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>LKP sample certificate</title><body style="max-width:900px;margin:40px auto;padding:20px">${content}<p style="font:12px Arial;text-align:center">Sample only. Use your browser’s Print → Save as PDF to save a PDF copy.</p></body></html>`,'LKP-SAMPLE-'+c.reference.replace(/[^a-zA-Z0-9_-]/g,'')+'.html','text/html');return;}openModal(`${content}<button class="button spacer" data-action="download-certificate" data-id="${esc(c.id)}">Download sample HTML ↓</button><p class="fine spacer">Open the downloaded file and choose Print → Save as PDF if needed.</p>`);}
document.addEventListener('click',async event=>{
 const el=event.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,pid=el.dataset.id,v=el.dataset.value;
 if(a==='project')showProject(pid);
 else if(a==='announcement'){const x=data.announcements.find(x=>x.id===pid);if(x)openModal(`<div class="eyebrow">Community board · ${date(x.date)}</div><h2 id="modal-title">${esc(x.title)}</h2><p class="preline">${esc(x.body)}</p>${x.sample?notice('Sample announcement'):''}`);}
 else if(a==='filter-projects'){projectFilter=v;render(false);}
 else if(a==='filter-finance'){financeFilter=v;render(false);}
 else if(a==='logout'){session=null;portalTab='overview';render(false);toast('Logged out of the demo.');}
 else if(a==='portal-tab'){portalTab=v;render(false);}
 else if(a==='export-csv')exportCSV();
 else if(a==='export-json'){if(requireOfficer())download(JSON.stringify({notice:'LKP browser mockup backup. Contains fictional data only.',...data},null,2),'LKP-DEMO-backup.json','application/json');}
 else if(a==='certificate')certificate(pid);
 else if(a==='download-certificate')certificate(pid,true);
 else if(a==='delete-project'){
  if(!requireOfficer())return;
  const project=data.projects.find(item=>item.id===pid);
  if(!project||!window.confirm(`Delete "${project.title}" from MongoDB?`))return;
  try{await apiProject(`/${encodeURIComponent(pid)}`,{method:'DELETE'});data.projects=data.projects.filter(item=>item.id!==pid);save(`Deleted MongoDB project: ${project.title}`);render(false);toast('Project deleted from MongoDB.');}
  catch(error){toast(error.message);}
 } else if(a==='reset-confirm'){try{localStorage.removeItem(STORE_KEY);}catch{}data=clone(SEED);session=null;portalTab='overview';financeFilter='All';projectFilter='All';projectQuery='';closeModal();render(false);toast('Demo restored to its original sample data.');}
 else if(a.startsWith('new-')||a.startsWith('edit-'))editor(a.replace(/^(new|edit)-/,''),pid);
 else if(a==='application-status'||a==='suggestion-status'){if(!requireOfficer())return;const list=a==='application-status'?data.applications:data.suggestions;const x=list.find(x=>x.id===pid);if(!x)return;x.status=v;save(`${a==='application-status'?'Application':'Suggestion'} marked ${v}: ${x.title||x.name}`);render(false);toast('Demo status updated.');}
});
document.addEventListener('input',event=>{if(event.target.id==='project-search'){projectQuery=event.target.value;document.querySelector('#project-results').innerHTML=projectResults();}});
document.addEventListener('submit',async event=>{
 const form=event.target;if(!(form instanceof HTMLFormElement))return;event.preventDefault();if(!form.reportValidity())return;const raw=new FormData(form),values=Object.fromEntries([...raw].map(([k,v])=>[k,String(v).trim()]));const error=form.querySelector('.form-error');const fail=message=>{if(error)error.textContent=message;};
 if([...form.querySelectorAll('[required]')].some(e=>e.type!=='checkbox'&&!e.value.trim())){fail('Please complete each required field.');return;}
 if(form.id==='login-form'){const validPass=values.password==='LKPdemo2026!';if(validPass&&values.username==='member.lkp'){session={id:'m1',role:'member',name:data.members.find(m=>m.id==='m1').name};}else if(validPass&&values.username==='officer.lkp'){session={id:'demo-officer',role:'officer',name:'Demo Officer'};}else{fail('The username or password is incorrect. Use a sample account shown above.');return;}portalTab='overview';render(false);toast('Welcome to the '+session.role+' demo.');}
 else if(form.id==='volunteer-form'){data.applications.unshift({...values,id:id('application-'),date:today(),status:'Pending'});save('Demo volunteer application submitted');form.innerHTML='<div class="form-success field full"><h3>Demo application saved.</h3><p>This fictional application is now available in Officer portal → Applications. It has not been sent to LKP and no member account was created.</p><a class="text-link" href="#portal">Explore the portal ↗</a></div>';toast('Saved locally for officer review.');}
 else if(form.id==='suggestion-form'){data.suggestions.unshift({...values,id:id('suggestion-'),date:today(),status:'Pending'});save('Demo suggestion submitted');form.innerHTML='<div class="form-success"><h3>Your idea is in the demo review queue.</h3><p>Log in as an officer and approve it under Suggestions to see it on the community board.</p><a class="text-link" href="#portal">Open demo portal ↗</a></div>';toast('Demo suggestion saved for review.');}
 else if(form.dataset.memberForm){if(!requireOfficer())return;const m=data.members.find(m=>m.id===form.dataset.memberForm);if(!m)return;m.status=values.status;m.hours=Number(values.hours);save('Updated sample member: '+m.name);render(false);toast('Sample member updated.');}
 else if(form.dataset.editor){if(!requireOfficer())return;const kind=form.dataset.editor,rid=form.dataset.id;
  if(kind==='announcement'){const item={...values,id:rid||id('announcement-'),sample:true};const i=data.announcements.findIndex(x=>x.id===rid);if(i>=0)data.announcements[i]=item;else data.announcements.unshift(item);}
  if(kind==='project'){
   const old=data.projects.find(x=>x.id===rid)||{};
   const item={...old,...values,sample:true,image:old.image||'',icon:old.icon||({Health:'heart',Environment:'leaf',Sports:'ball',Education:'book',Leadership:'people','Animal welfare':'paw',Fundraising:'flower'}[values.category]),source:old.source||'Mock data created through the LKP website'};
   try{
    const result=await apiProject(rid?`/${encodeURIComponent(rid)}`:'',{method:rid?'PUT':'POST',body:JSON.stringify(item)});
    const saved=normalizeProject(result.data);
    const i=data.projects.findIndex(x=>x.id===saved.id);
    if(i>=0)data.projects[i]=saved;else data.projects.unshift(saved);
   }catch(error){fail(error.message);return;}
  }
  if(kind==='transaction'){const amount=Number(values.amount);if(!Number.isFinite(amount)||amount<=0||amount>100000000){fail('Enter a valid positive amount up to PHP 100,000,000.');return;}const item={...values,amount,id:rid||id('transaction-')};const i=data.transactions.findIndex(x=>x.id===rid);if(i>=0)data.transactions[i]=item;else data.transactions.unshift(item);}
  if(kind==='certificate'){data.certificates.unshift({...values,id:id('certificate-'),reference:'DEMO-LKP-'+(data.certificates.length+1).toString().padStart(3,'0')});}
  save(`${rid?'Edited':'Added'} demo ${kind}: ${values.title||values.description}`);closeModal();render(false);toast(kind==='project'?'Project saved to MongoDB.':'Demo '+kind+' saved in this browser.');
 }
});
document.querySelector('.menu-toggle').addEventListener('click',event=>{const nav=document.querySelector('nav');const open=nav.classList.toggle('open');event.currentTarget.setAttribute('aria-expanded',String(open));event.currentTarget.setAttribute('aria-label',open?'Close navigation':'Open navigation');});
document.querySelector('.skip').addEventListener('click',event=>{event.preventDefault();main.focus();main.scrollIntoView({block:'start'});});
document.querySelector('.modal-close').addEventListener('click',closeModal);
modal.addEventListener('click',event=>{if(event.target===modal){const r=modal.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeModal();}});
document.querySelector('#reset-demo').addEventListener('click',()=>openModal('<h2 id="modal-title">Reset this demo?</h2><p>This removes only this mockup’s saved browser changes, applications, and suggestions, then restores its original sample records.</p><button class="button" data-action="reset-confirm">Reset demo data</button>'));
document.addEventListener('keydown',event=>{if(event.key==='Escape'){document.querySelector('nav').classList.remove('open');document.querySelector('.menu-toggle').setAttribute('aria-expanded','false');}});
document.querySelector('#year').textContent=new Date().getFullYear();
window.addEventListener('hashchange',()=>{if(modal.open)closeModal();render();});
render(false);
loadProjectsFromDatabase();
if(!storageOK)toast('Saved browser data could not be loaded. Running with sample data.');


